function friendly(PDOException $e){ $m=$e->getMessage(); if(stripos($m,'Duplicate')!==false) return 'Ya existe un registro con alguno de los datos únicos proporcionados.'; if(stripos($m,'materias requisito')!==false) return 'El alumno no cumple con los prerrequisitos necesarios para esta materia.'; return 'No fue posible completar la operación. Verifica los datos y sus relaciones.'; }
try{if($_SERVER['REQUEST_METHOD']==='POST'){ $id=postInt('id');$as=postInt('asignacion');$d=$_POST['dia']??'';$hi=$_POST['inicio']??'';$hf=$_POST['fin']??'';$au=trim($_POST['aula']??'');if(!in_array($d,['lunes','martes','miercoles','jueves','viernes','sabado'])||$hf<=$hi||!$as||!$au)throw new Exception('Horario inválido.');$sql='SELECT h.id FROM horarios h JOIN materia_profesor mp0 ON mp0.id=? JOIN materia_profesor mp ON mp.id=h.asignacion WHERE h.dia=? AND ? < h.hora_fin AND ? > h.hora_inicio AND (h.aula=? OR mp.profesor=mp0.profesor OR mp.grupo=mp0.grupo)'.($id?' AND h.id<>?':'');$s=$pdo->prepare($sql);$args=[$as,$d,$hi,$hf,$au];if($id)$args[]=$id;$s->execute($args);if($s->fetch())throw new Exception('Existe un conflicto de horario por aula, profesor o grupo.');$s=$id?$pdo->prepare('UPDATE horarios SET asignacion=?,dia=?,hora_inicio=?,hora_fin=?,aula=? WHERE id=?'):$pdo->prepare('INSERT INTO horarios(asignacion,dia,hora_inicio,hora_fin,aula) VALUES(?,?,?,?,?)');$s->execute($id?[$as,$d,$hi,$hf,$au,$id]:[$as,$d,$hi,$hf,$au]);$mensaje='Horario guardado.';}}catch(PDOException $e){$error=true;$mensaje=friendly($e);}catch(Exception $e){$error=true;$mensaje=$e->getMessage();}$asignaciones=$pdo->query('SELECT mp.id,m.nombre materia,p.nombre profesor,g.nombre grupo FROM materia_profesor mp JOIN materias m ON m.id=mp.materia JOIN profesores p ON p.id=mp.profesor JOIN grupos g ON g.id=mp.grupo WHERE mp.estado=1 ORDER BY g.nombre,m.nombre')->fetchAll();$horarios=$pdo->query('SELECT h.*,m.nombre materia,p.nombre profesor,g.nombre grupo FROM horarios h JOIN materia_profesor mp ON mp.id=h.asignacion JOIN materias m ON m.id=mp.materia JOIN profesores p ON p.id=mp.profesor JOIN grupos g ON g.id=mp.grupo ORDER BY h.dia,h.hora_inicio')->fetchAll();
